-- ---- Vérifications (la migration échoue si le compte n'y est pas) ----------

do $check$
declare
	v_cp integer;
	v_ce1 integer;
	v_ce2 integer;
	v_sans_noeud integer;
	v_fluence integer;
begin
	select count(*) into v_cp from public.curriculum_points where grade = 'CP';
	select count(*) into v_ce1 from public.curriculum_points where grade = 'CE1';
	select count(*) into v_ce2 from public.curriculum_points where grade = 'CE2';
	select count(*) into v_sans_noeud from public.curriculum_points
	 where grade in ('CP', 'CE1', 'CE2') and node_id is null;
	select count(*) into v_fluence from public.curriculum_points
	 where grade in ('CP', 'CE1', 'CE2') and regime_acquisition = 'fluence';
	if v_cp <> 69 or v_ce1 <> 82 or v_ce2 <> 76 or v_sans_noeud <> 0 or v_fluence <> 30 then
		raise exception 'seed cycle 2 incohérent : CP=%, CE1=%, CE2=%, sans nœud=%, fluence=%',
			v_cp, v_ce1, v_ce2, v_sans_noeud, v_fluence;
	end if;
end $check$;
